class BPETokenizer:
   end_of_word = '</w>'#表示单词结束的标记
   unknown_token = '<unk>'#表示未知单词的标记

   def __init__(self):
      self.merge_rules = []
      self.token_to_id = {}
      self.id_to_token = {}
   @property#属性式访问
   def vocab_size(self):
      return len(self.token_to_id)
   def count_tokens(self, text):
    pairs = Counter()
    for token in text:
        for left, right in zip(token, token[1:]):
            pairs[(left, right)] += 1
    return pairs
   def merge_tokens(self,tokens, pairs):
     new_tokens = []
     index=0
     while index<len(tokens):
          can_merge = (index+1<len(tokens)and tokens[index]==pairs[0]and tokens[index + 1] == pairs[1])
          if can_merge:
            new_tokens.append(pairs[0]+pairs[1])
            index += 2
          else:
            new_tokens.append(tokens[index])
            index += 1
     return new_tokens
   def merge_pair(self, text, pairs):
    return [self.merge_tokens(token, pairs) for token in text]
   def train(self, text, num_steps):
    self.merge_rules = []
    self.token_to_id = {}
    self.id_to_token = {}
    pairs = [list(word)+[self.end_of_word] for word in text.split()]
    vocabulary={self.unknown_token,self.end_of_word}
    for word in text.split():
        for char in word:
            vocabulary.add(char)
    for step in range(num_steps):
        pair_counts = self.count_tokens(pairs)
        if not pair_counts:
            break
        best_pair = max(pair_counts, key=pair_counts.get)
        best_count = pair_counts[best_pair]
        pairs=self.merge_pair(pairs, best_pair)
        self.merge_rules.append(best_pair)
        merge_token = best_pair[0]+best_pair[1]
        vocabulary.add(merge_token)
        print(f"第{step+1}步：",best_pair,"出现次数：",best_count)
    self.token_to_id = {token: i for i, token in enumerate(vocabulary)}
    self.id_to_token = {i: token for i, token in enumerate(vocabulary)}
    print("训练完成")
    print("词汇表大小：",self.vocab_size)
    return pairs
   def encode_word(self, word):
    tokens=(list(word)+[self.end_of_word])
    for pair in self.merge_rules:
        tokens=self.merge_tokens(tokens,pair)
    return tokens

   def tokenize(self, text):
    tokens=[]
    for word in text.split():
       word_tokens=self.encode_word(word)
       tokens.extend(word_tokens)
    return tokens
   def encode(self, text):
      if not self.token_to_id:raise RuntimeError("Tokenizer还没有训练或加载")
      tokens=self.tokenize(text)
      unknown_id=self.token_to_id.get(self.unknown_token)
      token_ids=[self.token_to_id.get(token,unknown_id) for token in tokens]
      return token_ids
   def decode(self, token_ids):
    if not self.id_to_token:raise RuntimeError("Tokenizer还没有训练或加载")
    tokens=[self.id_to_token[token_id] for token_id in token_ids]
    text="".join(tokens)
    text=text.replace(self.end_of_word," ")
    return text.rstrip()
   def save(self, path):
    file_path=Path(path)
    file_path.parent.mkdir(parents=True, exist_ok=True)
    data={
       "merge_rules": [
                [left, right]
                for left, right
                in self.merge_rules
            ],
            "token_to_id": self.token_to_id
        }
    with open(file_path, "w",encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"tokenizer已保存到 {file_path}")
   @classmethod
   def load(cls, path):
    file_path=Path(path)
    with open(file_path, "r",encoding="utf-8") as f:
        data = json.load(f)
    tokenizer = cls()
    tokenizer.merge_rules = [tuple(rule) for rule in data["merge_rules"]]
    tokenizer.token_to_id = {token: i for token, i in data["token_to_id"].items()}
    tokenizer.id_to_token = {token_id: token for token, token_id in tokenizer.token_to_id.items()}
    return tokenizer

class RMSNorm(nn.Module):
    def __init__(self, dim, eps=1e-5):
        super().__init__()
        self.eps=eps
        self.weight=nn.Parameter(torch.ones(dim))
    def forward(self, x):
        mean_square=x.pow(2).mean(dim=-1, keepdim=True)
        inverse_rms=torch.rsqrt(mean_square+self.eps)
        return x*inverse_rms*self.weight

def create_norm(embedding_dim, norm_type):
    if norm_type == "rmsnorm":
        return RMSNorm(embedding_dim)
    if norm_type == "layer_norm":
        return nn.LayerNorm(embedding_dim,elementwise_affine=True,bias=False)
    raise ValueError(f"未知的归一化类型：{norm_type}")

class MultiHeadAttention(nn.Module):
    def __init__(self,embedding_dim,num_heads,max_seq_len):
        super().__init__()
        self.num_heads=num_heads
        if embedding_dim%num_heads!=0:
            raise ValueError("embedding_dim must be divisible by num_heads")
        self.num_size=(embedding_dim//num_heads)
        self.heads=nn.ModuleList(
            [CausalSelfAttention(embedding_dim=embedding_dim, head_size=self.num_size, max_seq_len=max_seq_len) for _ in range(num_heads)]
        )
        self.output_proj=nn.Linear(embedding_dim, embedding_dim, bias=False)
    def forward(self,x,past_kv=None,use_cache=False):
        if past_kv is None:
            past_kv=[None for _ in range(self.num_heads)]
        head_outputs=[]
        new_head_cache=[]
        for head, head_past_kv in zip(self.heads, past_kv):
            output, new_cache=head(x, past_kv=head_past_kv, use_cache=use_cache)
            head_outputs.append(output)
            if use_cache:
               new_head_cache.append(new_cache)
        combined=torch.cat(head_outputs, dim=-1)
        output=self.output_proj(combined)
        if use_cache:
            return(output,new_head_cache)
        return output, None

class GELUFeedForward(nn.Module):
    def __init__(self,embedding_dim,feedforward_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(embedding_dim,feedforward_dim,bias=False),
            nn.GELU(),
            nn.Linear(feedforward_dim,embedding_dim,bias=False)
        )
    def forward(self, x):
        return self.net(x)

def create_feedforward(embedding_dim,feedforward_dim,feedforward_type):
    if feedforward_type == "swiglu":
        return SwiGLUFeedForward(embedding_dim,feedforward_dim)
    if feedforward_type == "gelu":
        gelu_hidden_dim = int( feedforward_dim * 3 / 2)
        return GELUFeedForward(embedding_dim,gelu_hidden_dim )
    raise ValueError(
        f"未知的前馈网络类型：{feedforward_type}"
    )

